#!/usr/bin/env node
// Self-contained Ancient Pulls V71 installation repair. No network access.
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { gunzipSync } from 'node:zlib';
const payload = JSON.parse(gunzipSync(Buffer.from('', 'base64')));
const args = process.argv.slice(2);
const apply = args.includes('--apply');
const fail = message => { console.error(message); process.exit(1); };
if (args.some(a => a.startsWith('--') && a !== '--apply')) fail('Usage: node repair-astral-71.mjs [project-folder] [--apply]');
const target = fs.realpathSync(path.resolve(args.find(a => !a.startsWith('--')) || process.cwd()));
const hash = bytes => crypto.createHash('sha256').update(bytes).digest('hex');
const readHash = file => hash(fs.readFileSync(file));
const exists = file => fs.existsSync(file);
if (!exists(path.join(target, 'package.json'))) fail('Run this from the existing project folder containing package.json.');
const roots = [target, path.join(target, 'src')].filter(p => exists(path.join(p, 'app/layout.tsx')) || exists(path.join(p, 'app/layout.js')));
if (roots.length !== 1) fail('Cannot identify one active app folder. Nothing changed.');
const appRoot = roots[0];
if (fs.lstatSync(appRoot).isSymbolicLink()) fail('The active source root is a symlink; review the project layout manually.');
const config = path.join(target, 'tsconfig.json');
const alias = exists(config) && fs.readFileSync(config, 'utf8').match(/"@\/\*"\s*:\s*\[\s*"([^"]+)"/);
if (!alias || path.resolve(target, alias[1].replace(/\*$/, '')) !== appRoot) fail('The @/ alias must point to the active app root. Nothing changed.');
function safePath(root, rel) {
  const full = path.resolve(root, rel);
  if (!full.startsWith(root + path.sep)) fail('Invalid package path.');
  let current = root;
  for (const part of path.relative(root, full).split(path.sep)) {
    current = path.join(current, part);
    if (exists(current) && fs.lstatSync(current).isSymbolicLink()) fail('Refusing to modify a symlink: ' + current);
  }
  return full;
}
const changes = [], conflicts = [], duplicates = [];
for (const file of payload.files) {
  const bytes = Buffer.from(file.data, 'base64');
  if (hash(bytes) !== file.sha256) fail('Repair payload is damaged: ' + file.path);
  const to = safePath(/^(app|components|lib)\//.test(file.path) ? appRoot : target, file.path);
  if (exists(to)) {
    const current = readHash(to);
    if (current === file.sha256 || file.mode === 'dependency') continue;
    if (!file.previousSha256.includes(current)) { conflicts.push(file.path); continue; }
  }
  changes.push({ to, bytes });
}
// Only relocate an identifiable, unedited copy of the delivered V71 source.
// Anything unfamiliar is left alone for a manual merge.
function checkCopy(dir, rel = '') {
  for (const entry of fs.readdirSync(path.join(dir, rel), { withFileTypes: true })) {
    if (entry.name === '.git') fail('Nested folder is a Git checkout. Move or merge it manually: ' + dir);
    if (['node_modules', '.next', '__pycache__'].includes(entry.name)) continue;
    const name = path.posix.join(rel, entry.name), full = path.join(dir, name);
    if (entry.isSymbolicLink()) fail('Nested folder contains a symlink. Move it outside the project manually: ' + dir);
    if (entry.isDirectory()) checkCopy(dir, name);
    else if (/\.(tsx?|jsx?|[mc][jt]s|css|json)$/.test(name) && payload.tree[name] !== readHash(full))
      fail('Nested folder contains an unfamiliar edit. Nothing changed. Review or move it outside the project first: ' + full);
  }
}
for (const rel of ['ancient-pulls', 'Ancient-Pulls-V71/ancient-pulls', 'source']) {
  const dir = safePath(target, rel);
  if (!exists(path.join(dir, 'app')) && !exists(path.join(dir, 'components/player/WishCinematic.tsx'))) continue;
  const layout = path.join(dir, 'app/layout.tsx');
  if (!exists(layout) || readHash(layout) !== payload.tree['app/layout.tsx'])
    fail('An unrecognised nested source folder exists. Move it outside the project first: ' + dir);
  checkCopy(dir);
  duplicates.push(dir);
}
if (conflicts.length) fail('Newer edits need a manual merge; nothing changed:\n' + conflicts.join('\n'));
console.log(`Active application: ${appRoot}\nFiles to update: ${changes.length}\nVerified nested copies to move outside the project: ${duplicates.length}`);
if (!apply) { console.log('Check passed. Add --apply to repair.'); process.exit(0); }
if (!changes.length && !duplicates.length) { console.log('Already repaired. Run npm run build.'); process.exit(0); }
const backup = fs.mkdtempSync(path.join(path.dirname(target), path.basename(target) + '-astral71-backup-'));
const written = [], moved = [];
try {
  for (const dir of duplicates) {
    const saved = path.join(backup, 'nested', path.relative(target, dir));
    fs.mkdirSync(path.dirname(saved), { recursive: true });
    fs.renameSync(dir, saved);
    moved.push({ original: dir, saved });
  }
  for (const item of changes) {
    const relative = path.relative(target, item.to);
    const saved = path.join(backup, 'files', relative), existed = exists(item.to);
    if (existed) { fs.mkdirSync(path.dirname(saved), { recursive: true }); fs.copyFileSync(item.to, saved); }
    fs.mkdirSync(path.dirname(item.to), { recursive: true });
    written.push({ file: item.to, saved, existed });
    fs.writeFileSync(item.to, item.bytes);
  }
  fs.writeFileSync(path.join(backup, 'restore.json'), JSON.stringify({ target, written, moved }, null, 2));
  console.log(`Repair complete. Backup: ${backup}\nRun npm run build, then commit the updated active files AND the removal of the nested copy. Deploy through your existing project.`);
} catch (error) {
  for (const item of written.reverse()) {
    if (item.existed) fs.copyFileSync(item.saved, item.file); else fs.rmSync(item.file, { force: true });
  }
  for (const item of moved.reverse()) fs.renameSync(item.saved, item.original);
  fail('Repair failed; modified files were restored: ' + error.message);
}
